package ru.practicum.booking;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import ru.practicum.booking.model.Booking;

public interface BookingRepository extends JpaRepository<Booking, Long> {
    @Query(value = "SELECT COUNT(*) > 0 FROM bookings b WHERE b.item_id = :itemId AND b.booker_id = :userId", nativeQuery = true)
    boolean existsByItemIdAndUserId(@Param("itemId") long itemId, @Param("userId") long userId);
}

package ru.practicum.booking.model;

import jakarta.persistence.*;
import lombok.Data;
import ru.practicum.item.model.Item;
import ru.practicum.user.model.User;

import java.time.LocalDateTime;

@Entity
@Table(name = "bookings")
@Data
public class Booking {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "booker_id", nullable = false)
    private User booker;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "item_id", nullable = false)
    private Item item;

    @Column(name = "start_date", nullable = false)
    private LocalDateTime start;

    @Column(name = "end_date", nullable = false)
    private LocalDateTime end;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private Status status;

}

